[package]
name = "sortedcontainers"
version = "0.1.0"
edition = "2021"
description = "Dependency-free Rust port of the sortedcontainers C++ header, with the test6 entry point"
publish = false

# No dependencies: the standard library only.
[dependencies]

[lib]
name = "sortedcontainers"
path = "src/lib.rs"

# The entry point lives in the package root, as `test6.rs`.
[[bin]]
name = "test6"
path = "test6.rs"

[profile.release]
opt-level = 3
=== test6.rs ===
//! Rust port of `tests/test6.cpp`.
//!
//! Builds two sorted sets -- `0..n` and the even numbers `0, 2, ..., 2n-2` --
//! unions them, then reports the three sizes followed by a membership check for
//! every value in `0..n`.
//!
//! The single optional argument is the count `n`, defaulting to 6, and is
//! parsed with C `atoi` semantics so that non-numeric input becomes 0 exactly
//! as it did in the original.

#[path = "src/lib.rs"]
mod sortedcontainers;

use std::io::{self, BufWriter, Write};

use sortedcontainers::{c_atoi, SortedSet};

fn main() {
    let argv: Vec<String> = std::env::args_os()
        .map(|arg| arg.to_string_lossy().into_owned())
        .collect();

    let mut n: i32 = 6;
    if argv.len() > 1 {
        n = c_atoi(&argv[1]);
    }

    let mut s1: SortedSet<i32> = SortedSet::new();
    let mut s2: SortedSet<i32> = SortedSet::new();
    let mut i: i32 = 0;
    while i < n {
        s1.insert(i);
        // Wrapping mirrors what the C++ `int` arithmetic does on overflow.
        s2.insert(i.wrapping_mul(2));
        i = i.wrapping_add(1);
    }

    let s3 = s1.union_with(&s2);

    // `std::cout` is line-buffered by `endl`; one buffered writer, flushed at
    // the end, produces the same bytes.
    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());

    writeln!(out, "{}", s1.len()).expect("write to stdout");
    writeln!(out, "{}", s2.len()).expect("write to stdout");
    writeln!(out, "{}", s3.len()).expect("write to stdout");

    let mut i: i32 = 0;
    while i < n {
        // `std::cout` prints a bool as 1 or 0 without `boolalpha`.
        write!(out, "{} ", u8::from(s3.contains(&i))).expect("write to stdout");
        i = i.wrapping_add(1);
    }
    writeln!(out).expect("write to stdout");

    out.flush().expect("flush stdout");
}

