use std::iter::FromIterator;

pub struct S(Vec<i32>);

impl FromIterator<i32> for S {
    fn from_iter<I: IntoIterator<Item = i32>>(iter: I) -> Self {
        S(iter.into_iter().collect())
    }
}

fn main() {
    let s: S = (0..3).collect();
    println!("{}", s.0.len());
}
